INSERT INTO `module_settings` VALUES (1,'transactions','TRANSACTIONS','Transactions','Auto numbering formats, POS transaction defaults, and void approval controls.',1,'Admin, Manager, Staff',2,'2026-04-14 03:32:51','2026-09-10 12:16:45','v1.0','Aug 05, 2026'),(3,'fuel_management','FUEL MANAGEMENT','Fuel Management','Fuel reconciliation tolerance rules, calibration computation, and meter validations.',1,'Admin, Manager, Staff',3,'2026-04-14 03:32:51','2026-08-06 13:39:10','v1.0','Aug 05, 2026'),(4,'calendar','CALENDAR','Calendar','Public holidays config, shift reminder notifications, and equipment schedules.',1,'Admin, Manager, Staff',7,'2026-04-14 03:32:51','2026-08-06 13:39:10','v1.0','Aug 05, 2026'),(5,'reports','REPORTS','Reports','PDF, Excel, and CSV export modules, header/footer branding setups.',1,'Admin, Manager, Staff',8,'2026-04-14 03:32:51','2026-08-06 13:39:10','v1.0','Aug 05, 2026'),(851,'inventory','INVENTORY','Inventory','FIFO accounting rules, low/critical stock threshold levels, and batch tracking.',1,'Admin, Manager, Staff',4,'2026-05-06 15:12:51','2026-08-24 05:58:48','v1.0','Aug 05, 2026'),(852,'customers','CUSTOMERS','Customers','Customer registration setup, vehicle service history logs, credit and fleet cards.',1,'Admin, Manager, Staff',5,'2026-05-06 15:12:51','2026-08-06 13:39:10','v1.0','Aug 05, 2026'),(1143,'dashboard','DASHBOARD','Dashboard','System dashboard KPI cards, real-time charts, and quick action configurations.',1,'Admin, Manager, Staff',1,'2026-08-06 06:52:46','2026-08-21 07:55:21','v1.0','Aug 05, 2026'),(1148,'product_pricing','PRODUCT PRICING','Product & Pricing','SKU/Barcode code validation, price change approval workflows, and price histories.',1,'Admin, Manager, Staff',6,'2026-08-06 06:52:46','2026-08-06 13:39:10','v1.0','Aug 05, 2026'),(1151,'notifications','NOTIFICATIONS','Notifications','Alert banner durations, low stock alerts, backups, and approval popups.',1,'Admin, Manager, Staff',9,'2026-08-06 06:52:46','2026-08-06 13:39:10','v1.0','Aug 05, 2026'),(1152,'backup_restore','BACKUP RESTORE','Backup & Restore','Automated background DB backups, retention policies, and storage cleanup.',1,'Admin, Manager, Staff',10,'2026-08-06 06:52:46','2026-08-06 13:39:10','v1.0','Aug 05, 2026'),(1153,'audit_trail','AUDIT TRAIL','Audit Trail','System error monitoring, log levels, automated database log archiving.',1,'Admin, Manager, Staff',11,'2026-08-06 06:52:46','2026-08-06 13:39:10','v1.0','Aug 05, 2026'),(1154,'api_integration','API INTEGRATION','API / Integration','Third-party REST integrations, webhooks, SMTP, and SMS Gateways.',1,'Admin, Manager, Staff',12,'2026-08-06 06:52:46','2026-08-06 13:39:10','v1.0','Aug 05, 2026');
